import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p67_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor gelu_globalavgpool_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_globalavgpool_cuda", &gelu_globalavgpool_cuda, "Fused GELU + Global Average Pool (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused GELU (erf-based) + Global Average Pool kernel.
// Each block handles one (n, c) slice of the NCHW input tensor.
// Threads stride over H*W, accumulate gelu(v), then block-reduce and write mean.
__global__ void gelu_gavgpool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int HW,
    int C
) {
    // block index encodes (n, c)
    int nc = blockIdx.x;
    int n = nc / C;
    int c = nc % C;
    const float* base = input + (n * C + c) * HW;

    float partial = 0.0f;
    // Each thread strides over spatial positions
    for (int i = threadIdx.x; i < HW; i += blockDim.x) {
        float v = base[i];
        // erf-based GELU matching PyTorch default
        partial += 0.5f * v * (1.0f + erff(v * 0.7071067811865476f));
    }

    // Warp-level reduction via shuffle
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        partial += __shfl_down_sync(mask, partial, offset);
    }

    // Shared memory to collect warp sums
    __shared__ float smem[32]; // max 32 warps per block
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) smem[warp_id] = partial;
    __syncthreads();

    // First warp reduces warp sums
    int num_warps = (blockDim.x + 31) >> 5;
    float total = 0.0f;
    if (threadIdx.x < num_warps) {
        total = smem[threadIdx.x];
        for (int offset = 16; offset > 0; offset >>= 1) {
            total += __shfl_down_sync(mask, total, offset);
        }
    }

    if (threadIdx.x == 0) {
        output[nc] = total / static_cast<float>(HW);
    }
}

torch::Tensor gelu_globalavgpool_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");
    TORCH_CHECK(x.dim() == 4, "Input must be 4D (N, C, H, W)");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int HW = H * W;

    auto output = torch::empty({N, C}, x.options());

    int block_size = 256;
    int grid_size = N * C;

    gelu_gavgpool_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        HW,
        C
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a convolution, applies GELU, and then performs global average pooling.
        """
    def __init__(self, in_channels, out_channels, kernel_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, in_channels, height, width)
                Returns:
                    Output tensor of shape (batch_size, out_channels)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = _stark_get_extension().gelu_globalavgpool_cuda(x.contiguous())
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # Pooling is fused into the custom CUDA kernel above; no separate pooling needed.
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # Fused CUDA kernel already returns shape (batch_size, out_channels); no squeeze needed.
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

